mapper.sql:
WHERE t.user_id = #{filter.userId}

  AND (LOCATE(#{filter.keyword}, t.title) > 0 OR LOCATE(#{filter.keyword}, t.destination) > 0)


  AND t.start_date > #{filter.today}
  AND t.end_date < #{filter.today}
  AND t.start_date <= #{filter.today} AND t.end_date >= #{filter.today}

mapper.select:
SELECT t.*, COALESCE(e.actual_expense, 0) AS actual_expense FROM trip t
LEFT JOIN (
  SELECT ex.trip_id, SUM(ex.amount) AS actual_expense FROM expense ex
  JOIN trip owned ON owned.trip_id = ex.trip_id WHERE owned.user_id = #{filter.userId}
  GROUP BY ex.trip_id
) e ON e.trip_id = t.trip_id

ORDER BY t.created_at DESC, t.trip_id DESC LIMIT #{size} OFFSET #{offset}

mapper.sql:
FROM attraction a LEFT JOIN favorite f ON f.attraction_id = a.attraction_id AND f.user_id = #{filter.userId}
WHERE 1=1
AND a.created_by = #{filter.userId}
AND f.favorite_id IS NOT NULL
AND LOCATE(#{filter.keyword}, a.name) > 0
AND a.city = #{filter.city}

mapper.select:
SELECT a.*, CASE WHEN f.favorite_id IS NULL THEN FALSE ELSE TRUE END AS favorited, f.favorite_id, f.created_at AS favorite_created_at
ORDER BY f.created_at DESC, f.favorite_id DESC ORDER BY a.created_at DESC, a.attraction_id DESC
LIMIT #{size} OFFSET #{offset}

mapper.sql:
WHERE trip_id = #{filter.tripId}
AND category = #{filter.category}
AND spent_on >= #{filter.startDate}
AND spent_on <= #{filter.endDate}

mapper.select:
SELECT ai_plan_id, user_id, trip_id, request_json, estimated_total, status, error_message, created_at, saved_at
FROM ai_plan_record 
ORDER BY created_at DESC, ai_plan_id DESC LIMIT #{size} OFFSET #{offset}

SELECT e.category, SUM(e.amount) AS amount FROM expense e JOIN trip t ON t.trip_id = e.trip_id
WHERE t.user_id = #{userId} AND t.trip_id = #{tripId}
GROUP BY e.category ORDER BY e.category
